#!/usr/bin/env bash
# СУДИТ: hooks/metrics-collector.sh
# probe_D443.sh — «Проверка» пункта D443: `_backlog_open()` в `hooks/metrics-collector.sh`
# (:544-547) отвечает ОДНИМ кодом и на «пункт закрыт», и на «файла BACKLOG.md нет вовсе», и
# это смешение доходит до ОТЧЁТА (`state/metrics.md`), который читает владелец.
# Результат: при истинно ОТСУТСТВУЮЩЕМ файле долга отчёт metrics.md несёт заметку «статус
#            … НЕ ПРОВЕРЕН», которой нет при легитимно ЗАКРЫТОМ пункте на существующем
#            файле — «файла нет» и «пункт закрыт» различимы В ВЫВОДЕ СБОРЩИКА, а не только
#            в возврате внутренней функции. «Пункт открыт» / «пункт закрыт» на СУЩЕСТВУЮЩЕМ
#            файле мехванизм различал и до правки — это положительный контроль, не предмет.
# Проверка результата: bash hooks/tests/fixtures/probe_D443.sh → 0. Сегодня 1 (дефект
#            наблюдён: отчёт при отсутствующем файле долга ничем не отличается от отчёта
#            при закрытом пункте), 2 — рамка не собралась.
#
# ПЕРЕСОБРАНО 17 сентября 2026 разбором скептика (три претензии, все устранены здесь):
#   1. Уровень результата — раньше судился код возврата функции, извлечённой sed'ом; ни один
#      из девяти вызывающих (:563-683) этот код не читает — значение без потребителя.
#      Теперь судится РЕАЛЬНЫЙ вывод сборщика (`state/metrics.md`, секция «Предупреждения»),
#      куда решение фактически доходит (или не доходит) до владельца.
#   2. Форма починки — извлечение sed'ом судило РОВНО ту форму фикса, что стояла в первой
#      версии green_D443 (правка внутри самой функции). Доктринальная починка на стороне
#      вызывающего (по образцу `unread_or`/GENTLE_CORPUS, :566) осталась бы красной. Теперь
#      судится ТОЛЬКО конечный отчёт — фикс может стоять где угодно.
#   3. Хрупкость по окружению — унаследованный `$CLAUDSOUL_BACKLOG` (его уважает сам
#      механизм, :543, и экспортируют несколько тестов дерева) ронял пробу рамкой. Здесь он
#      явно `unset` перед каждым прогоном.
#
# Механизм под судом — ВЕСЬ `hooks/metrics-collector.sh`, взятый из CLAUDSOUL_REPO (зелёная
# сторона подставляет копию с починкой), плюс обязательная `hooks/lib/unread-lib.sh` (без неё
# сборщик падает на первом же `unread_or` — родовое решение B, а не запасная ветка). Исполнение
# требует ITR_SESSIONS_TOTAL > 0 (иначе ветка с `_backlog_open` не определяется вовсе — это
# отдельный, более широкий дефект и здесь не судится), поэтому STATE_DIR несёт минимальную
# intrusiveness-history.jsonl (одна сессия) и rework-fired-*.jsonl (30 строк) — так открытый
# D18 даёт наблюдаемую строку в отчёте, и есть чем проверить, что механизм в принципе способен
# сказать «открыт». Живой ~/.claude не читается: HOME/LESSONS_DIR/STATE_DIR — в песочнице.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/../../.." && pwd)"
MECH="${CLAUDSOUL_REPO:-$ROOT}"
SRC="$MECH/hooks/metrics-collector.sh"
# unread-lib.sh — ИНФРАСТРУКТУРА для запуска, а не предмет суда: под судом только
# metrics-collector.sh. Берётся у MECH, если зелёная сторона несёт свою копию, иначе — у
# ROOT (обычный случай: зелёная сторона правит только сам сборщик, как в мкфикс-примере).
LIB="$MECH/hooks/lib/unread-lib.sh"; [ -f "$LIB" ] || LIB="$ROOT/hooks/lib/unread-lib.sh"
[ -f "$SRC" ] || { echo "probe_D443: нет $SRC" >&2; exit 2; }
[ -f "$LIB" ] || { echo "probe_D443: нет $LIB (unread-lib обязательна, запасной ветки нет)" >&2; exit 2; }
command -v jq >/dev/null 2>&1 || { echo "probe_D443: нужен jq" >&2; exit 2; }
T=$(mktemp -d) || { echo "probe_D443: нет временного каталога" >&2; exit 2; }
trap 'rm -rf "$T"' EXIT

mkdir -p "$T/mech/hooks/lib" "$T/state" "$T/lessons" "$T/home" "$T/root_open" "$T/root_closed" "$T/root_absent"
cp "$SRC" "$T/mech/hooks/metrics-collector.sh" || exit 2
cp "$LIB" "$T/mech/hooks/lib/unread-lib.sh" || exit 2

# ITR_SESSIONS_TOTAL > 0: одна минимальная сессия — остальные поля дефолтятся `// 0` внутри
# jq-агрегатора, крашей это не даёт (проверено на живом дереве при сборке пробы).
printf '%s\n' '{"session_id":"s1","closed_at":"2026-01-01T00:00:00Z"}' > "$T/state/intrusiveness-history.jsonl"
# REWORK_FIRED ≥ REWORK_MIN_SAMPLE (дефолт 30, hooks/metrics-collector.sh) — считается строками.
i=0; : > "$T/state/rework-fired-test.jsonl"
while [ "$i" -lt 30 ]; do printf '{"n":%d}\n' "$i" >> "$T/state/rework-fired-test.jsonl"; i=$((i + 1)); done

printf '# BACKLOG\n\n- ☐ **D18** тест\n' > "$T/root_open/BACKLOG.md"
printf '# BACKLOG\n\n- ☑ **D18** тест\n' > "$T/root_closed/BACKLOG.md"
# "$T/root_absent" — каталог для проверки создаётся, BACKLOG.md в нём умышленно нет.

run() {  # run <CLAUDSOUL_ROOT> → печатает секцию «## Предупреждения» отчёта metrics.md
    ( unset CLAUDSOUL_BACKLOG
      HOME="$T/home" LESSONS_DIR="$T/lessons" STATE_DIR="$T/state" CLAUDSOUL_ROOT="$1" \
          bash "$T/mech/hooks/metrics-collector.sh" >/dev/null 2>&1 )
    awk '/^## Предупреждения$/{f=1} f' "$T/state/metrics.md" 2>/dev/null
}

# Положительный контроль 1: пункт ОТКРЫТ на существующем файле — механизм и до правки умеет
# сказать «открыт» (строка про D18 — реальный, не изобретённый пробой, наблюдаемый эффект).
OUT_OPEN=$(run "$T/root_open")
grep -q 'D18' <<< "$OUT_OPEN" || { echo "probe_D443: контроль — на ОТКРЫТОМ D18 отчёт не назвал D18 — рамка не собралась (вывод: ${OUT_OPEN:-пусто})" >&2; exit 2; }
grep -qi 'не провер' <<< "$OUT_OPEN" && { echo "probe_D443: контроль — на ОТКРЫТОМ D18 отчёт уже несёт «не провер» — рамка не различает состояния" >&2; exit 2; }

# Положительный контроль 2: пункт ЗАКРЫТ на существующем файле — тишина про D18, и НИКАКОЙ
# заметки «не провер» (файл есть, статус легитимно известен).
OUT_CLOSED=$(run "$T/root_closed")
grep -q 'D18' <<< "$OUT_CLOSED" && { echo "probe_D443: контроль — на ЗАКРЫТОМ D18 отчёт всё равно назвал D18 (вывод: $OUT_CLOSED)" >&2; exit 2; }
if grep -qi 'не провер' <<< "$OUT_CLOSED"; then
    echo "probe_D443: контроль — ЗАКРЫТЫЙ пункт на существующем файле ошибочно помечен «не провер» — фикс размётил не то состояние" >&2
    exit 2
fi

# Суд: файла BACKLOG.md нет вовсе (CLAUDSOUL_ROOT — пустой каталог).
OUT_ABSENT=$(run "$T/root_absent")
ABSENT_MARKED=0; grep -qi 'не провер' <<< "$OUT_ABSENT" && ABSENT_MARKED=1

if [ "$OUT_ABSENT" = "$OUT_CLOSED" ]; then
    echo "probe_D443: дефект — отчёт при ОТСУТСТВУЮЩЕМ файле долга и при ЗАКРЫТОМ пункте совпадает буква в букву" >&2
    exit 1
fi
if [ "$ABSENT_MARKED" -eq 0 ]; then
    echo "probe_D443: дефект — отчёт при ОТСУТСТВУЮЩЕМ файле долга не несёт отметки «не провер», хотя отличается от закрытого чем-то посторонним (вывод: ${OUT_ABSENT:-пусто})" >&2
    exit 1
fi
exit 0
